<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class ReturnTransaction extends Model { protected $table = 'returns'; protected $guarded = []; public function supplier() { return $this->belongsTo(Supplier::class); } public function createdBy() { return $this->belongsTo(User::class, 'created_by'); } public function items() { return $this->hasMany(ReturnItem::class); } }